<script setup lang="ts">
import { isFieldVisible, type FieldSchema } from '@/lib/form-schema'
import type { RequestForm } from '../../shared/domain'
defineProps<{ fields: FieldSchema[]; model: RequestForm; errors: Record<string, string>; validating?: boolean }>()
const emit = defineEmits<{ change: [key: keyof RequestForm, value: string | number]; blur: [key: keyof RequestForm] }>()
function update(field: FieldSchema, event: Event) { const value = (event.target as HTMLInputElement).value; emit('change', field.key, field.type === 'number' ? Number(value) : field.key === 'creditCode' ? value.toUpperCase() : value) }
</script>
<template><div class="form-grid"><div v-for="field in fields.filter(f => isFieldVisible(f, model))" :key="field.key" class="form-field" :class="{ full: field.full, invalid: errors[field.key] }"><label :for="`field-${field.key}`">{{ field.label }}<span v-if="field.required" class="required">*</span><span v-if="field.key === 'creditCode' && validating" class="validating">正在核查…</span></label><select v-if="field.type === 'select'" :id="`field-${field.key}`" :value="model[field.key]" :aria-invalid="!!errors[field.key]" @change="update(field, $event)"><option v-for="option in field.options" :key="option.value" :value="option.value">{{ option.label }}</option></select><textarea v-else-if="field.type === 'textarea'" :id="`field-${field.key}`" :value="String(model[field.key])" :placeholder="field.placeholder" rows="4" maxlength="3000" :aria-invalid="!!errors[field.key]" @input="update(field, $event)" @blur="emit('blur', field.key)" /><input v-else :id="`field-${field.key}`" :type="field.type" :value="model[field.key]" :placeholder="field.placeholder" :min="field.type === 'number' ? 0 : undefined" :max="field.type === 'number' ? 100000000 : undefined" :maxlength="field.key === 'creditCode' ? 18 : 100" :step="field.type === 'number' ? '0.01' : undefined" :aria-invalid="!!errors[field.key]" @input="update(field, $event)" @blur="emit('blur', field.key)" /><p v-if="errors[field.key]" class="field-error">{{ errors[field.key] }}</p><p v-else-if="field.help" class="field-help">{{ field.help }}</p></div></div></template>
